import java.io.BufferedOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;

public class mandelbrot {
    private static final int MAX_ITERATIONS = 50;

    public static void main(String[] args) throws Exception {
        final int n = Integer.parseInt(args[0]);
        final int rowBytes = n / 8 + ((n & 7) == 0 ? 0 : 1);

        final double[] real = new double[n];
        for (int x = 0; x < n; x++) {
            real[x] = 2.0 * x / n - 1.5;
        }

        final byte[][] rows = new byte[n][];
        final Object rowMonitor = new Object();
        final AtomicInteger nextRow = new AtomicInteger();

        int threadCount = Math.min(
                n,
                Math.min(32, Math.max(1, Runtime.getRuntime().availableProcessors()))
        );

        final Semaphore pendingSlots = new Semaphore(Math.max(1, threadCount * 2));
        Thread[] workers = new Thread[threadCount];

        for (int i = 0; i < threadCount; i++) {
            workers[i] = new Thread(() -> {
                try {
                    while (true) {
                        pendingSlots.acquire();

                        int y = nextRow.getAndIncrement();
                        if (y >= n) {
                            pendingSlots.release();
                            return;
                        }

                        byte[] row = renderRow(y, n, rowBytes, real);

                        synchronized (rowMonitor) {
                            rows[y] = row;
                            rowMonitor.notifyAll();
                        }
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
            workers[i].setDaemon(true);
            workers[i].start();
        }

        try (BufferedOutputStream out = new BufferedOutputStream(System.out, 65536)) {
            String header = "P4\n" + n + " " + n + "\n";
            out.write(header.getBytes(StandardCharsets.US_ASCII));

            for (int y = 0; y < n; y++) {
                byte[] row;
                synchronized (rowMonitor) {
                    while ((row = rows[y]) == null) {
                        rowMonitor.wait();
                    }
                    rows[y] = null;
                }

                out.write(row);
                pendingSlots.release();
            }

            out.flush();
        }

        for (Thread worker : workers) {
            worker.join();
        }
    }

    private static byte[] renderRow(int y, int n, int rowBytes, double[] real) {
        byte[] row = new byte[rowBytes];
        double ci = 2.0 * y / n - 1.0;

        int x = 0;
        for (int byteIndex = 0; byteIndex < rowBytes; byteIndex++) {
            int bits = 0;
            int count = Math.min(8, n - x);

            for (int bit = 0; bit < count; bit++, x++) {
                bits <<= 1;
                if (isInSet(real[x], ci)) {
                    bits |= 1;
                }
            }

            bits <<= 8 - count;
            row[byteIndex] = (byte) bits;
        }

        return row;
    }

    private static boolean isInSet(double cr, double ci) {
        double ci2 = ci * ci;

        double shifted = cr - 0.25;
        double q = shifted * shifted + ci2;
        if (q * (q + shifted) <= 0.25 * ci2) {
            return true;
        }

        double bulb = cr + 1.0;
        if (bulb * bulb + ci2 <= 0.0625) {
            return true;
        }

